"""Reports API: composition over verified content, generated by a background job."""

from __future__ import annotations

import uuid
from typing import Any

from fastapi import APIRouter, Depends, Request
from sqlalchemy import select

from pandit_server import jobs
from pandit_server.api.v1.profiles import owned_profile
from pandit_server.compose.reports import VALID_DOMAINS
from pandit_server.db.models import JobRun, Report
from pandit_server.deps import ContainerDep, SessionDep, UserDep, limited
from pandit_server.errors import ApiError, not_found
from pandit_server.platform_services import record_audit
from pandit_server.schemas import ReportCreate

router = APIRouter(prefix="/reports", tags=["reports"], dependencies=[Depends(limited())])


def _out(report: Report, job_id: uuid.UUID | None = None) -> dict[str, Any]:
    out: dict[str, Any] = {
        "id": str(report.id),
        "profile_id": str(report.profile_id),
        "status": report.status,
        "domains": dict(report.domains).get("domains", []),
        "created_at": report.created_at.isoformat() if report.created_at else None,
    }
    if job_id is not None:
        out["job_id"] = str(job_id)
    if report.content is not None:
        out["content"] = report.content
    return out


@router.post("", status_code=202, dependencies=[Depends(limited("expensive"))])
def create_report(
    body: ReportCreate,
    request: Request,
    user: UserDep,
    session: SessionDep,
    container: ContainerDep,
) -> dict[str, Any]:
    unknown = sorted(set(body.domains) - VALID_DOMAINS)
    if unknown:
        raise ApiError(
            422,
            "unknown_domain",
            "Unknown life domain.",
            details={"unknown": unknown, "supported": sorted(VALID_DOMAINS)},
        )
    profile = owned_profile(session, user, body.profile_id)
    if profile.birth_time is None:
        raise ApiError(422, "birth_time_required", "A report needs the birth time.")
    report = Report(
        user_id=user.id,
        profile_id=profile.id,
        domains={
            "domains": list(dict.fromkeys(body.domains)),
            "language": body.language,
            "subject_adult_confirmed": body.subject_adult_confirmed,
        },
        status="pending",
    )
    session.add(report)
    job = JobRun(user_id=user.id, kind="report", status="queued")
    session.add(job)
    session.flush()
    record_audit(
        session,
        subject=user.subject,
        action="report.create",
        resource_type="report",
        resource_id=str(report.id),
        request_id=getattr(request.state, "request_id", None),
    )
    job_id, report_id = job.id, report.id
    # The job must see the committed rows: commit this transaction, then enqueue.
    session.commit()
    try:
        jobs.enqueue_report(job_id, report_id)
    except Exception as exc:  # noqa: BLE001
        jobs.finish_job(container, job_id, status="failed", error_code="queue_unavailable")
        raise ApiError(503, "queue_unavailable", "Background processing is unavailable.") from exc
    session.refresh(report)
    return _out(report, job_id)


@router.get("")
def list_reports(user: UserDep, session: SessionDep) -> dict[str, Any]:
    rows = session.scalars(
        select(Report).where(Report.user_id == user.id).order_by(Report.created_at.desc()).limit(50)
    ).all()
    return {"items": [{k: v for k, v in _out(r).items() if k != "content"} for r in rows]}


@router.get("/{report_id}")
def get_report(report_id: uuid.UUID, user: UserDep, session: SessionDep) -> dict[str, Any]:
    report = session.scalar(select(Report).where(Report.id == report_id, Report.user_id == user.id))
    if report is None:
        raise not_found("report")
    return _out(report)


@router.delete("/{report_id}", status_code=204)
def delete_report(report_id: uuid.UUID, user: UserDep, session: SessionDep) -> None:
    report = session.scalar(select(Report).where(Report.id == report_id, Report.user_id == user.id))
    if report is None:
        raise not_found("report")
    session.delete(report)
